'use strict';
(function(){
  let lesson=null,timer=null,returnTo=null;
  const steps=[['เดินไปหาเป้าซ้อม','จอยซ้าย หรือ WASD · เดินอย่างน้อย 60 หน่วย'],['โจมตีเป้าซ้อม','กดปุ่มโจมตีค้าง หรือ Space เมื่ออยู่ในระยะ'],['ใช้สกิลหลัก','ลากปุ่มสกิล Q เพื่อเล็ง แล้วปล่อย'],['ซื้อไอเทม','กดร้านค้า แล้วซื้อไอเทมหนึ่งชิ้น']];
  const panel=document.createElement('section');panel.id='practiceGuide';panel.hidden=true;panel.setAttribute('aria-label','ฝึกควบคุม');document.body.appendChild(panel);
  function render(){if(!lesson)return;panel.innerHTML=`<div><b>ฝึกควบคุม · ${Math.max(0,120-Math.floor((Date.now()-lesson.started)/1000))} วิ</b><span>${lesson.step<4?'ขั้น '+(lesson.step+1)+' / 4 · '+steps[lesson.step][0]:'ฝึกครบแล้ว พร้อมเข้าห้องเรียน'}</span><small>${lesson.step<4?steps[lesson.step][1]:'ใช้ความรู้และช่วยเพื่อนตามแผนของทีม'}</small></div><button id="endPractice">${lesson.step<4?'กลับห้องเรียน':'ฝึกเสร็จ · กลับห้องเรียน'}</button>`;document.getElementById('endPractice').onclick=stop;}
  function complete(step){if(lesson?.step===step){lesson.step++;render();}}
  function stop(){if(!lesson)return;lesson=null;clearInterval(timer);panel.hidden=true;originals.lobby();const callback=returnTo;returnTo=null;callback?.();}
  window.RiftPractice={start(callback){if(net.session&&!net.session.classroom)return;detachClassMatch();returnTo=callback;document.getElementById('classroom').hidden=true;document.body.classList.remove('education-open');const oldMode=net.mode;if(education.details?.student?.hero)chooseHero(education.details.student.hero);net.mode='solo';originals.start();net.mode=oldMode;const p=game.player;p.x=680;p.y=500;p.gold=1500;p.damage=Math.max(65,p.damage);const target=hero(1,1,HEROES.find(h=>h.id==='bulwark'),false);target.x=780;target.y=500;target.hp=target.maxHp=50000;target.remoteHuman=true;target.control={move:{x:0,y:0},attack:false};target.damage=0;target.clientName='เป้าซ้อม';game.entities=[p,target];game.wave=1000000;game.practice=true;game.finished=false;lesson={step:0,x:p.x,y:p.y,started:Date.now(),seenAt:Date.now()};panel.hidden=false;render();timer=setInterval(()=>{if(!game?.practice)return stop();if(education.session&&Date.now()-lesson.seenAt>5000){const active=lesson;lesson.seenAt=Date.now();void lessonRequest('classes/'+education.session.code+'?compact=1').then(d=>{if(lesson!==active)return;window.riftClassConnection?.(true);if(d.phase!=='waiting')stop();}).catch(()=>{if(lesson===active)window.riftClassConnection?.(false);});}if(lesson.step===0&&Math.hypot(game.player.x-lesson.x,game.player.y-lesson.y)>=60)complete(0);if(Date.now()-lesson.started>=120000)stop();else render();},500);},stop};
  const beforeStrike=strike;strike=function(p,t){const old=p.attack;const result=beforeStrike(p,t);if(game?.practice&&p.player&&t&&p.attack>old)complete(1);return result;};
  const beforeSkill=useSkill;useSkill=function(key,actor,aim){const result=beforeSkill(key,actor,aim);if(game?.practice&&(!actor||actor.player)&&key==='q'&&result!==false)complete(2);return result;};
  const beforeBuy=buy;buy=function(id,actor){const result=beforeBuy(id,actor);if(game?.practice&&(!actor||actor.player)&&result?.ok)complete(3);return result;};
})();
